using LastRail.Presentation.MissionShell;
using NUnit.Framework;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {public sealed class MonthlyAttendanceValidationTests {
 sealed class Journal:IAccountActionJournal {public PendingAccountAction Row;public PendingAccountAction Read(string id)=>Row?.Account==id?Row:null;public bool Save(PendingAccountAction a){Row=a;return true;}public bool Remove(PendingAccountAction a){Row=null;return true;}}
 sealed class Wire:IRunApiHttpTransport {public readonly List<RunApiHttpRequest> Requests=new List<RunApiHttpRequest>();public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply=r=>Task.FromResult(RunApiHttpResponse.NetworkError("unavailable"));public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest r){Requests.Add(r);return Reply(r);}}
 sealed class Registry:IMonthlyAttendanceRegistry {public string CurrentActivityId=>"monthly-test";}
 static GameApiAuthSessionSnapshot Session()=>new GameApiAuthSessionSnapshot("account_test","ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
 static string Body()=>new JObject{["policyVersion"]="monthly-test",["cycleId"]="2026-09",["expectedRevision"]=0}.ToString();
 [Test] public async Task MissingDiscoveryCannotGuessActivityOrGrant(){var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>1);await state.EnterMonthlyAttendanceAsync();Assert.That(wire.Requests.Count,Is.EqualTo(1));Assert.That(wire.Requests[0].EndpointPath,Is.EqualTo("/v1/attendance/monthly/current"));Assert.That(state.MonthlyReady,Is.False);Assert.That(state.PrepareMonthlyRecovery(),Is.Null);}
 [Test] public async Task CalendarOpeningIsReadOnly(){var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>1,new Registry());await state.RefreshMonthlyAttendanceAsync();Assert.That(wire.Requests.Count,Is.EqualTo(1));Assert.That(wire.Requests[0].Method,Is.EqualTo("GET"));Assert.That(wire.Requests[0].EndpointPath,Is.EqualTo("/v1/attendance/monthly-test/monthly"));}
 [Test] public async Task UnknownAndMalformedReceiptsRetainExactOriginalCommand(){var action=new PendingAccountAction("account_test","monthly-auto","monthly-test",0,"original:/+",Body());var journal=new Journal{Row=action};var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await state.RetryPendingAsync();wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,"{\"accepted\":true}"));await state.RetryPendingAsync();Assert.That(journal.Row,Is.SameAs(action));Assert.That(state.LastMonthlyReceipt,Is.Null);Assert.That(wire.Requests.Count,Is.EqualTo(2));foreach(var r in wire.Requests){Assert.That(r.BodyJson,Is.EqualTo(action.Payload));Assert.That(System.Linq.Enumerable.Single(r.Headers,h=>h.Name=="Idempotency-Key").Value,Is.EqualTo(action.Key));}}
 [Test] public async Task LateReadCannotPopulateChangedAccount(){var wire=new Wire();var session=Session();long generation=1;var pending=new TaskCompletionSource<RunApiHttpResponse>();wire.Reply=r=>pending.Task;using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>generation,new Registry());var read=state.RefreshMonthlyAttendanceAsync();generation++;state.SynchronizeSession();pending.SetResult(RunApiHttpResponse.Success(200,"{}"));await read;Assert.That(state.MonthlyAttendance,Is.Null);Assert.That(state.MonthlyError,Is.Null);Assert.That(state.MonthlyLoading,Is.False);}
 [Test] public async Task OldAccountEntryDoesNotSuppressNewAccountEntry(){var wire=new Wire();var session=Session();long generation=1;var first=new TaskCompletionSource<RunApiHttpResponse>();var second=new TaskCompletionSource<RunApiHttpResponse>();wire.Reply=r=>wire.Requests.Count==1?first.Task:second.Task;using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>generation,new Registry());var old=state.EnterMonthlyAttendanceAsync();generation++;state.SynchronizeSession();var next=state.EnterMonthlyAttendanceAsync();Assert.That(wire.Requests.Count,Is.EqualTo(2));first.SetResult(RunApiHttpResponse.NetworkError("old"));await old;await state.EnterMonthlyAttendanceAsync();Assert.That(wire.Requests.Count,Is.EqualTo(2),"Old finally must not unlock new entry");second.SetResult(RunApiHttpResponse.NetworkError("new"));await next;}
 [Test] public void StrictCommandRejectsExtraFieldsAndPaidAmountOutsideQuoteRange(){Assert.DoesNotThrow(()=>MonthlyAttendanceContract.Request("monthly-auto","monthly-test",Body()));var body=JObject.Parse(Body());body["reward"]=999;Assert.Throws<FormatException>(()=>MonthlyAttendanceContract.Request("monthly-auto","monthly-test",body.ToString()));body.Remove("reward");body["walletPolicyVersion"]="wallet";body["confirmedPaid"]=101;Assert.Throws<FormatException>(()=>MonthlyAttendanceContract.Request("monthly-recovery","monthly-test",body.ToString()));}
} }
